#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

// Pares de faces opostas:
// 0 (A) <-> 5 (F)
// 1 (B) <-> 3 (D)
// 2 (C) <-> 4 (E)
int opposite_face(int f) {
    if (f == 0) return 5;
    if (f == 5) return 0;
    if (f == 1) return 3;
    if (f == 3) return 1;
    if (f == 2) return 4;
    if (f == 4) return 2;
    return -1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<vector<int>> dice(n, vector<int>(6));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 6; ++j) {
            cin >> dice[i][j];
        }
    }

    int best_total = 0;

    // Tenta cada uma das 6 faces para ser a face inferior do primeiro dado
    for (int bottom_face_idx = 0; bottom_face_idx < 6; ++bottom_face_idx) {
        int current_sum = 0;
        int top_val = 0;

        // Primeiro dado
        int bottom_idx = bottom_face_idx;
        int top_idx = opposite_face(bottom_idx);
        top_val = dice[0][top_idx];

        int max_side = 0;
        for (int f = 0; f < 6; ++f) {
            if (f != bottom_idx && f != top_idx) {
                max_side = max(max_side, dice[0][f]);
            }
        }
        current_sum += max_side;

        // Dados seguintes
        for (int i = 1; i < n; ++i) {
            // A face inferior deve ter o valor top_val
            bottom_idx = -1;
            for (int f = 0; f < 6; ++f) {
                if (dice[i][f] == top_val) {
                    bottom_idx = f;
                    break;
                }
            }
            top_idx = opposite_face(bottom_idx);
            top_val = dice[i][top_idx];

            max_side = 0;
            for (int f = 0; f < 6; ++f) {
                if (f != bottom_idx && f != top_idx) {
                    max_side = max(max_side, dice[i][f]);
                }
            }
            current_sum += max_side;
        }

        best_total = max(best_total, current_sum);
    }

    cout << best_total << "\n";

    return 0;
}
